import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';

// Create a scene
const scene = new THREE.Scene();
const object = createScene();

// Apply -90 degrees X-rotation for Blender Z-up space
// Note: Three.js is Y-up. Blender is Z-up.
// Rotating -90 degrees around X will map Y to Z.
object.rotation.x = -Math.PI / 2;

scene.add(object);

// OBJExporter doesn't support InstancedMesh out of the box in older versions.
// Let's check and convert if necessary.
object.traverse((child) => {
    if (child.isInstancedMesh) {
        const mesh = new THREE.Group();
        mesh.name = child.name + '_instances';
        for (let i = 0; i < child.count; i++) {
            const instanceMesh = new THREE.Mesh(child.geometry, child.material);
            const matrix = new THREE.Matrix4();
            child.getMatrixAt(i, matrix);
            instanceMesh.applyMatrix4(matrix);
            mesh.add(instanceMesh);
        }
        child.parent.add(mesh);
        child.visible = false; // Hide the original instanced mesh
    }
});

// Update matrices
scene.updateMatrixWorld(true);

// Export
const exporter = new OBJExporter();
const result = exporter.parse(scene);

fs.writeFileSync('/root/output/object.obj', result);
console.log('Exported to /root/output/object.obj');
